// Hermetic node:test suite for the independent verifier (verify.mjs).
// Builds synthetic input trees in temp dirs; every expected receipt/report/annex/
// manifest value below is HAND-COMPUTED from the spec rules and written as a
// literal — nothing is generated by a re-implementation of the producer.
// Imports NOTHING from verify.mjs: it runs verify.mjs as a subprocess.
import { spawnSync } from 'node:child_process';
import { mkdirSync, mkdtempSync, readFileSync, readdirSync, rmSync, writeFileSync } from 'node:fs';
import { tmpdir } from 'node:os';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { fileURLToPath } from 'node:url';
import { test, after } from 'node:test';

const here = path.dirname(fileURLToPath(import.meta.url));
const VERIFY = path.join(here, '..', 'verify.mjs');

// ---- spec-fixed strings (restated for fixture literals) ----
const UNRESOLVED_NOTE =
  'no committed evidence of external intent; consistent with the subset-catalog claim (README) but unverified per code — intent unresolved';
const ANNEX_NOTE =
  'Every unresolved finding with example records, capped at 10 per class; exact totals live in report.json. Nothing here is an allowlist: entries document defects and their committed repair locations (REPAIR-LOCATIONS.md).';

const sha256 = (buf) => createHash('sha256').update(buf).digest('hex');
const canon = (v) => JSON.stringify(v, null, 2) + '\n';

// ---- synthetic raw inputs (hand-built) ----
// Clean tree: 2 buildings, 3 courses, 2 sections, 2 statuses.
// Defects planted so recomputed values are non-trivial but fully hand-checkable:
//   - wild-101-001: unresolved courseCode 'CHIN 4101' (sectionToCourse),
//     meeting end before start, unknown buildingId (meetingBounds, meetingToBuilding)
//   - courseStatuses['PHIL 4999'] unresolved (courseStatusToCourse)
//   - major-1 core 'MATH 4300' unresolved; CS 101's title annotates it
//     (majorCoreToCourse: evidence.courseCode must be the ANNOTATING course 'CS 101')
//   - CS 101 prerequisite 'UNKNOWN 101' external-unknown (prerequisites)
const CS101 = { id: 'cs-101', code: 'CS 101', title: 'Intro to Programming (MATH 4300)', creditHours: 3, description: 'intro', prerequisites: ['MATH 1010', 'UNKNOWN 101'] };
const MATH1010 = { id: 'math-1010', code: 'MATH 1010', title: 'Calculus I', creditHours: 4, description: 'limits', prerequisites: [] };
const PHYS2130 = { id: 'phys-2130', code: 'PHYS 2130', title: 'Physics for Scientists I', creditHours: 4, description: 'mechanics', prerequisites: [] };
const MATH_SEC = { id: 'math-1010-001', courseCode: 'MATH 1010', meetings: [
  { day: 'Mon', start: '09:00', end: '09:50', buildingId: 'bldg-mh' },
  { day: 'Wed', start: '09:00', end: '09:50', buildingId: 'bldg-mh' },
  { day: 'Fri', start: '09:00', end: '09:50', buildingId: 'bldg-mh' },
] };
const WILD_SEC = { id: 'wild-101-001', courseCode: 'CHIN 4101', meetings: [
  { day: 'Tue', start: '09:00', end: '08:00', buildingId: 'bldg-nope' },
] };
const CATALOG = {
  buildings: [
    { id: 'bldg-mh', name: 'Math Hall', shortName: 'MH' },
    { id: 'bldg-sh', name: 'Science Hall', shortName: 'SH' },
  ],
  courses: [CS101, MATH1010, PHYS2130],
  sections: [MATH_SEC, WILD_SEC],
  courseStatuses: { 'MATH 1010': 'active', 'PHIL 4999': 'inactive' },
};
// The majors literal must be valid JSON inside the TS export (the verifier
// JSON.parses the bracketed literal; the real seed-data.ts has the same shape).
const MAJORS_TS = `export const majors: Major[] = [
  {
    "id": "major-1",
    "name": "Computer Science",
    "coreCourseCodes": ["CS 101", "MATH 4300"]
  }
] as const;
`;
const CORPUS_A = [{ course_number: 'MATH 1010', title: 'Calculus I', description: 'limits' }];
const CORPUS_B = [{ data: [{ course_number: 'PHYS 2130', title: 'Physics for Scientists I', description: 'mechanics' }] }];
const COMPD = `course_number,section_number,professor,start_time,end_time,days,location
MATH 1010,001,Prof One,09:00,09:50,MWF,Math Hall (MH)
PHYS 2130,001,Prof Two,14:00,15:15,TuTh,Science Hall (SH)
PHIL 1010,001,Prof Three,10:00,10:50,M,Old Main (OM)
`;

// ---- hand-computed values for the clean tree ----
const CLEAN_COUNTS = {
  buildings: 2, courses: 3, sections: 2, majors: 1, courseStatusEntries: 2,
  sectionMeetings: 4, prerequisiteEdges: 2, corpusFiles: 2, compDRows: 3,
};
// Direction-4 semantics: evidence.courseCode = the ANNOTATING course's own code.
const MAJOR_CORE_EXAMPLE = {
  majorId: 'major-1', majorName: 'Computer Science', code: 'MATH 4300',
  evidence: { kind: 'titleAnnotatedEquivalent', courseCode: 'CS 101', title: 'Intro to Programming (MATH 4300)' },
};
const CLEAN_FINDINGS = {
  duplicateIds: {
    courseCodes: { total: 0, examples: [] },
    sectionIds: { total: 0, examples: [] },
    buildingIds: { total: 0, examples: [] },
  },
  meetingBounds: {
    meetingsChecked: 4,
    endTimeNotAfterStart: { total: 1, examples: [{ sectionId: 'wild-101-001', day: 'Tue', start: '09:00', end: '08:00' }] },
    malformedTime: { total: 0, examples: [] },
    dayOutsideCommittedVocabulary: { total: 0, examples: [] },
  },
  references: {
    sectionToCourse: { checked: 2, unresolved: { total: 1, examples: [{ sectionId: 'wild-101-001', courseCode: 'CHIN 4101' }] } },
    meetingToBuilding: { checked: 4, unresolved: { total: 1, examples: [{ sectionId: 'wild-101-001', buildingId: 'bldg-nope' }] } },
    courseStatusToCourse: { checked: 2, unresolved: { total: 1, examples: [{ code: 'PHIL 4999' }] } },
    majorCoreToCourse: { checked: 2, unresolved: { total: 1, examples: [MAJOR_CORE_EXAMPLE] } },
    prerequisites: {
      edgesTotal: 2, internalEdges: 1,
      external: {
        edges: 1, distinctCodes: 1,
        categories: {
          inSourceCorpus: { codes: 0, edges: 0, examples: [] },
          titleAnnotatedInBundle: { codes: 0, edges: 0, examples: [] },
          unknown: { codes: 1, edges: 1, examples: [{ code: 'UNKNOWN 101', edges: 1, category: 'unknown', evidence: null }], note: UNRESOLVED_NOTE },
        },
      },
    },
  },
};
const CLEAN_VIOLATIONS = { duplicateIds: 0, meetingBounds: 1, unknownReferences: 4 };
// compD rows: MATH#001 matches (MWF -> 3 meetings, agree); PHYS#001 and PHIL#001
// have no matching section in the catalog -> unmatched. Only MH is a matched short.
const CLEAN_PROVENANCE = {
  bound: true, path: 'data/compD.csv', submoduleCommit: null, rows: 3,
  sectionPairsMatched: 1, sectionPairsUnmatched: 2, meetingsFromDayPatterns: 3,
  sectionsMeetingsAgree: 1, sectionsMeetingsDisagree: 0,
  buildingShortCodes: 1, buildingCodesInBundle: 1, termColumns: [],
  assessment: 'stub — see producer',
};

function writeRepoInputs(repo) {
  mkdirSync(path.join(repo, 'data'), { recursive: true });
  mkdirSync(path.join(repo, 'frontend/src/lib'), { recursive: true });
  writeFileSync(path.join(repo, 'data/generated-catalog.json'), canon(CATALOG));
  writeFileSync(path.join(repo, 'frontend/src/lib/seed-data.ts'), MAJORS_TS);
  writeFileSync(path.join(repo, 'data/corpus-a.json'), canon(CORPUS_A));
  writeFileSync(path.join(repo, 'data/corpus-b.json'), canon(CORPUS_B));
  writeFileSync(path.join(repo, 'data/compD.csv'), COMPD);
}

function inputBindings(repo) {
  const buf = (p) => readFileSync(path.join(repo, p));
  return [
    { role: 'generated-catalog', path: 'data/generated-catalog.json', sha256: sha256(buf('data/generated-catalog.json')), bytes: buf('data/generated-catalog.json').length, present: true },
    { role: 'majors-source', path: 'frontend/src/lib/seed-data.ts', sha256: sha256(buf('frontend/src/lib/seed-data.ts')), bytes: buf('frontend/src/lib/seed-data.ts').length, present: true },
    { role: 'prerequisite-corpus', path: 'data/corpus-a.json', sha256: sha256(buf('data/corpus-a.json')), bytes: buf('data/corpus-a.json').length, present: true },
    { role: 'prerequisite-corpus', path: 'data/corpus-b.json', sha256: sha256(buf('data/corpus-b.json')), bytes: buf('data/corpus-b.json').length, present: true },
    { role: 'section-source', path: 'data/compD.csv', sha256: sha256(buf('data/compD.csv')), bytes: buf('data/compD.csv').length, present: true },
  ];
}

function evidenceFor(repo, { unbound = false } = {}) {
  const inputs = inputBindings(repo);
  if (unbound) {
    const i = inputs.findIndex((b) => b.role === 'section-source');
    inputs[i] = { ...inputs[i], present: false };
  }
  const receipt = {
    receiptVersion: 2, toolVersion: 2, rulesVersion: 2, generatedAt: '2026-10-10T12:00:00.000Z',
    inputs, submodulePins: [], counts: { compDRows: unbound ? 0 : 3 },
    corpusDigest: {
      algorithm: 'sha256',
      digest: sha256(Buffer.from(
        `${inputs[2].sha256}  data/corpus-a.json\n${inputs[3].sha256}  data/corpus-b.json\n`, 'utf8')),
    },
  };
  const report = {
    reportVersion: 2, toolVersion: 2, rulesVersion: 2, generatedAt: '2026-10-10T12:00:00.000Z',
    inputs,
    counts: { ...CLEAN_COUNTS, compDRows: unbound ? 0 : 3 },
    findings: CLEAN_FINDINGS,
    violations: CLEAN_VIOLATIONS,
    provenance: {
      sectionSource: unbound
        ? { bound: false, path: null, submoduleCommit: null, rows: 0, sectionPairsMatched: 0, sectionPairsUnmatched: 0, meetingsFromDayPatterns: 0, sectionsMeetingsAgree: 0, sectionsMeetingsDisagree: 0, buildingShortCodes: 0, buildingCodesInBundle: 0, termColumns: [], assessment: 'unbound — no section source; meeting data unverified' }
        : CLEAN_PROVENANCE,
    },
  };
  const annex = {
    unresolvedExamplesVersion: 2, toolVersion: 2, generatedAt: '2026-10-10T12:00:00.000Z', note: ANNEX_NOTE,
    referenceExamples: [
      { check: 'sectionToCourse', total: 1, examples: [{ sectionId: 'wild-101-001', courseCode: 'CHIN 4101' }] },
      { check: 'meetingToBuilding', total: 1, examples: [{ sectionId: 'wild-101-001', buildingId: 'bldg-nope' }] },
      { check: 'courseStatusToCourse', total: 1, examples: [{ code: 'PHIL 4999' }] },
      { check: 'majorCoreToCourse', total: 1, examples: [MAJOR_CORE_EXAMPLE] },
    ],
    externalPrerequisites: {
      edges: 1, distinctCodes: 1,
      categories: {
        inSourceCorpus: { codes: 0, edges: 0, examples: [] },
        titleAnnotatedInBundle: { codes: 0, edges: 0, examples: [] },
        unknown: { codes: 1, edges: 1, examples: [{ code: 'UNKNOWN 101', edges: 1, category: 'unknown', evidence: null }], note: UNRESOLVED_NOTE },
      },
    },
    provenanceSummary: unbound
      ? { bound: false, assessment: 'unbound — no section source; meeting data unverified' }
      : { bound: true, assessment: 'stub — see producer' },
  };
  const bytes = {
    'input-receipt.json': canon(receipt),
    'report.json': canon(report),
    'unresolved-examples.json': canon(annex),
  };
  const manifest = {
    manifestVersion: 1, generatedAt: '2026-10-10T12:00:00.000Z',
    files: {
      'input-receipt.json': { sha256: sha256(Buffer.from(bytes['input-receipt.json'], 'utf8')), bytes: Buffer.byteLength(bytes['input-receipt.json'], 'utf8') },
      'report.json': { sha256: sha256(Buffer.from(bytes['report.json'], 'utf8')), bytes: Buffer.byteLength(bytes['report.json'], 'utf8') },
      'unresolved-examples.json': { sha256: sha256(Buffer.from(bytes['unresolved-examples.json'], 'utf8')), bytes: Buffer.byteLength(bytes['unresolved-examples.json'], 'utf8') },
    },
  };
  return { manifest, bytes };
}

function buildTree({ mutate = null, unbound = false, rebuildManifest = true } = {}) {
  const base = mkdtempSync(path.join(tmpdir(), 'ccv2-'));
  const repo = path.join(base, 'repo');
  const results = path.join(base, 'results');
  mkdirSync(repo, { recursive: true });
  mkdirSync(results, { recursive: true });
  writeRepoInputs(repo);
  const ev = evidenceFor(repo, { unbound });
  if (unbound) rmSync(path.join(repo, 'data/compD.csv'));
  writeFileSync(path.join(results, 'input-receipt.json'), ev.bytes['input-receipt.json']);
  writeFileSync(path.join(results, 'report.json'), ev.bytes['report.json']);
  writeFileSync(path.join(results, 'unresolved-examples.json'), ev.bytes['unresolved-examples.json']);
  writeFileSync(path.join(results, 'results-manifest.json'), canon(ev.manifest));
  if (mutate) mutate(base, repo, results);
  if (rebuildManifest) {
    // Mutates may rewrite evidence files; keep manifest hashes in lockstep so each
    // test isolates exactly ONE check (byte-drift tests pass rebuildManifest:false).
    const entryFor = (name) => {
      const text = readFileSync(path.join(results, name), 'utf8');
      return { sha256: sha256(Buffer.from(text, 'utf8')), bytes: Buffer.byteLength(text, 'utf8') };
    };
    writeFileSync(path.join(results, 'results-manifest.json'), canon({
      manifestVersion: 1, generatedAt: '2026-10-10T12:00:00.000Z',
      files: {
        'input-receipt.json': entryFor('input-receipt.json'),
        'report.json': entryFor('report.json'),
        'unresolved-examples.json': entryFor('unresolved-examples.json'),
      },
    }));
  }
  return { base, repo, results };
}

function runVerifier(repo, results, extra = []) {
  const res = spawnSync('node', [VERIFY, '--results', results, '--repo-root', repo, ...extra], { encoding: 'utf8' });
  return { status: res.status, output: `${res.stdout ?? ''}${res.stderr ?? ''}` };
}

// 11 'ok' lines: parse, versions, manifest-bytes, canonical-bytes, input-binding,
// cross-binding, counts, findings, violations, provenance, examples-cap.
const OK_ALL = ['ok parse', 'ok versions', 'ok manifest-bytes', 'ok canonical-bytes', 'ok input-binding', 'ok cross-binding', 'ok counts', 'ok findings', 'ok violations', 'ok provenance', 'ok examples-cap'];

function assertOutputIncludes(res, needle) {
  if (!res.output.includes(needle)) {
    throw new Error(`expected output to include ${JSON.stringify(needle)}\n--- output ---\n${res.output}`);
  }
}

test('1. clean control: clean tree, compD bound — all 11 checks ok, exit 0', () => {
  const t = buildTree({});
  after(() => rmSync(t.base, { recursive: true, force: true }));
  const res = runVerifier(t.repo, t.results);
  for (const line of OK_ALL) assertOutputIncludes(res, line);
  assertOutputIncludes(res, 'verdict: PASS');
  if (res.status !== 0) throw new Error(`expected exit 0, got ${res.status}\n${res.output}`);
});

test('2. clean tree, compD unbound (absent from checkout): exit 0 with unbound provenance', () => {
  const t = buildTree({ unbound: true });
  after(() => rmSync(t.base, { recursive: true, force: true }));
  const res = runVerifier(t.repo, t.results);
  for (const line of OK_ALL) assertOutputIncludes(res, line);
  if (res.status !== 0) throw new Error(`expected exit 0, got ${res.status}\n${res.output}`);
});

test('3. versions tampered → FAIL versions', () => {
  const t = buildTree({
    mutate: (base, repo, results) => {
      const p = path.join(results, 'input-receipt.json');
      const r = JSON.parse(readFileSync(p, 'utf8'));
      r.rulesVersion = 3;
      writeFileSync(p, canon(r));
      const q = path.join(results, 'report.json');
      const rep = JSON.parse(readFileSync(q, 'utf8'));
      rep.rulesVersion = 3;
      writeFileSync(q, canon(rep));
      const a = path.join(results, 'unresolved-examples.json');
      const an = JSON.parse(readFileSync(a, 'utf8'));
      an.toolVersion = 1;
      writeFileSync(a, canon(an));
      const m = path.join(results, 'results-manifest.json');
      const man = JSON.parse(readFileSync(m, 'utf8'));
      man.manifestVersion = 2;
      writeFileSync(m, canon(man));
    },
  });
  after(() => rmSync(t.base, { recursive: true, force: true }));
  const res = runVerifier(t.repo, t.results);
  assertOutputIncludes(res, 'FAIL versions');
  if (res.status !== 1) throw new Error(`expected exit 1, got ${res.status}\n${res.output}`);
});

