test('13. example cap: a 25-defect class shows total 25 with exactly 10 stored examples, exit 0', () => {
  const t = buildTree({
    mutate: (base, repo, results) => {
      const catalog = JSON.parse(JSON.stringify(CATALOG));
      for (let i = 0; i < 25; i++) catalog.courses.push(JSON.parse(JSON.stringify(CS101)));
      writeFileSync(path.join(repo, 'data/generated-catalog.json'), canon(catalog));
      const catBytes = canon(catalog);
      const p = path.join(results, 'input-receipt.json');
      const r = JSON.parse(readFileSync(p, 'utf8'));
      r.inputs[0] = { role: 'generated-catalog', path: 'data/generated-catalog.json', sha256: sha256(Buffer.from(catBytes, 'utf8')), bytes: Buffer.byteLength(catBytes, 'utf8'), present: true };
      writeFileSync(p, canon(r));
      const q = path.join(results, 'report.json');
      const rep = JSON.parse(readFileSync(q, 'utf8'));
      rep.inputs = r.inputs;
      rep.counts.courses = 28; // 3 + 25
      rep.counts.prerequisiteEdges = 52; // each planted copy carries 2 edges
      rep.findings.duplicateIds.courseCodes = { total: 25, examples: Array.from({ length: 10 }, () => ({ code: 'CS 101' })) };
      rep.findings.references.prerequisites.edgesTotal = 52;
      rep.findings.references.prerequisites.internalEdges = 26; // 1 + 25 copies
      rep.findings.references.prerequisites.external.edges = 26; // 1 + 25 copies
      rep.findings.references.prerequisites.external.categories.unknown.edges = 26;
      rep.findings.references.prerequisites.external.categories.unknown.examples = [{ code: 'UNKNOWN 101', edges: 26, category: 'unknown', evidence: null }];
      rep.violations.duplicateIds = 25;
      writeFileSync(q, canon(rep));
      const a = path.join(results, 'unresolved-examples.json');
      const an = JSON.parse(readFileSync(a, 'utf8'));
      an.externalPrerequisites = rep.findings.references.prerequisites.external;
      writeFileSync(a, canon(an));
    },
  });
  after(() => rmSync(t.base, { recursive: true, force: true }));
  const res = runVerifier(t.repo, t.results);
  if (res.status !== 0) throw new Error(`expected exit 0, got ${res.status}\n${res.output}`);
  assertOutputIncludes(res, 'verdict: PASS');
});

test('14. >10 stored examples → FAIL examples-cap', () => {
  const t = buildTree({
    mutate: (base, repo, results) => {
      const catalog = JSON.parse(JSON.stringify(CATALOG));
      for (let i = 0; i < 11; i++) catalog.courses.push(JSON.parse(JSON.stringify(CS101)));
      writeFileSync(path.join(repo, 'data/generated-catalog.json'), canon(catalog));
      const catBytes = canon(catalog);
      const p = path.join(results, 'input-receipt.json');
      const r = JSON.parse(readFileSync(p, 'utf8'));
      r.inputs[0] = { role: 'generated-catalog', path: 'data/generated-catalog.json', sha256: sha256(Buffer.from(catBytes, 'utf8')), bytes: Buffer.byteLength(catBytes, 'utf8'), present: true };
      writeFileSync(p, canon(r));
      const q = path.join(results, 'report.json');
      const rep = JSON.parse(readFileSync(q, 'utf8'));
      rep.inputs = r.inputs;
      rep.counts.courses = 14; // 3 + 11
      rep.counts.prerequisiteEdges = 24; // each planted copy carries 2 edges
      rep.findings.duplicateIds.courseCodes = { total: 11, examples: Array.from({ length: 11 }, () => ({ code: 'CS 101' })) };
      rep.findings.references.prerequisites.edgesTotal = 24;
      rep.findings.references.prerequisites.internalEdges = 12; // 1 + 11 copies
      rep.findings.references.prerequisites.external.edges = 12; // 1 + 11 copies
      rep.findings.references.prerequisites.external.categories.unknown.edges = 12;
      rep.findings.references.prerequisites.external.categories.unknown.examples = [{ code: 'UNKNOWN 101', edges: 12, category: 'unknown', evidence: null }];
      rep.violations.duplicateIds = 11;
      writeFileSync(q, canon(rep));
    },
  });
  after(() => rmSync(t.base, { recursive: true, force: true }));
  const res = runVerifier(t.repo, t.results);
  assertOutputIncludes(res, 'FAIL examples-cap');
  if (res.status !== 1) throw new Error(`expected exit 1, got ${res.status}\n${res.output}`);
});

