test('18. --verdict-out inside the results dir is refused (exit 2)', () => {
  const t = buildTree({});
  after(() => rmSync(t.base, { recursive: true, force: true }));
  const before = readdirSync(t.results).sort();
  const res = runVerifier(t.repo, t.results, ['--verdict-out', path.join(t.results, 'report.json')]);
  if (res.status !== 2) throw new Error(`expected exit 2, got ${res.status}\n${res.output}`);
  const afterFiles = readdirSync(t.results).sort();
  if (JSON.stringify(before) !== JSON.stringify(afterFiles)) throw new Error('results dir changed');
});

test('19. --verdict-out outside the results dir is written, audited dir untouched', () => {
  const t = buildTree({});
  after(() => rmSync(t.base, { recursive: true, force: true }));
  const out = path.join(t.base, 'verdict.txt');
  const res = runVerifier(t.repo, t.results, ['--verdict-out', out]);
  if (res.status !== 0) throw new Error(`expected exit 0, got ${res.status}\n${res.output}`);
  const written = readFileSync(out, 'utf8');
  if (!written.includes('verdict: PASS')) throw new Error('verdict file lacks verdict line');
  if (readdirSync(t.results).length !== 4) throw new Error('audited dir gained files');
});

test('20. report disagrees with recomputation outside the bundle → FAIL counts', () => {
  const t = buildTree({
    mutate: (base, repo, results) => {
      const p = path.join(repo, 'data/generated-catalog.json');
      const c = JSON.parse(readFileSync(p, 'utf8'));
      c.buildings.push({ id: 'bldg-x', name: 'X Hall', shortName: 'XH' });
      const catBytes = canon(c);
      writeFileSync(p, catBytes);
      const r = JSON.parse(readFileSync(path.join(results, 'input-receipt.json'), 'utf8'));
      r.inputs[0] = { role: 'generated-catalog', path: 'data/generated-catalog.json', sha256: sha256(Buffer.from(catBytes, 'utf8')), bytes: Buffer.byteLength(catBytes, 'utf8'), present: true };
      writeFileSync(path.join(results, 'input-receipt.json'), canon(r));
      const q = JSON.parse(readFileSync(path.join(results, 'report.json'), 'utf8'));
      q.inputs = r.inputs;
      // counts.buildings stays 2 in the report — recomputation says 3 → FAIL counts
      writeFileSync(path.join(results, 'report.json'), canon(q));
    },
  });
  after(() => rmSync(t.base, { recursive: true, force: true }));
  const res = runVerifier(t.repo, t.results);
  assertOutputIncludes(res, 'FAIL counts');
  if (res.status !== 1) throw new Error(`expected exit 1, got ${res.status}\n${res.output}`);
});

